FILES={'creation/materials.py': {'source': 'geo-monitor-deploy/creation/materials.py', 'before': '800a0064796025a5f0ad1d10c17f7666095e60b61f254b0ec98a2f0b749b1695', 'text': '"""Creation-only observations. No receiver, PostgreSQL writes, or GEO bridge."""\nfrom datetime import datetime,timedelta\nimport json,os,re,sqlite3,subprocess,time\nfrom pathlib import Path\nfrom zoneinfo import ZoneInfo\nfrom geo_source_cards.runtime import atomic_json,atomic_write\n\nROOT=Path(os.environ.get(\'GEO_CREATION_MATERIAL_ROOT\',\'/opt/monitor/geo-content/materials\'))\nLEGACY=Path(\'/home/user/geo-editorial/runtime-api\')\nGEO=Path(\'/opt/monitor/geo-capture\');ZONE=ZoneInfo(\'Asia/Shanghai\')\nCONTENT_BASE=Path(\'/opt/monitor/geo-content\')\nSEARCH_POOL=CONTENT_BASE/\'search-pool\'\nCHANNELS={\'deepseek\':\'DeepSeek\',\'baidu_ai\':\'百度卡片\',\'wenxin_card\':\'文心卡片\'}\n\ndef collector_directory(path,owner):\n """Collector user must traverse every private ancestor, including UMask=0077 parents."""\n root=ROOT.resolve();path=Path(path)\n if ROOT.is_symlink() or path.is_symlink() or (path.resolve()!=root and root not in path.resolve().parents):raise ValueError(\'采集目录不在专用素材目录内\')\n base=CONTENT_BASE.resolve()\n if base in root.parents:\n  # Only the collector\'s group gets traversal; no directory listing or world access.\n  os.chown(base,-1,owner.pw_gid);base.chmod((base.stat().st_mode&0o770)|0o010)\n  current=base\n  for part in path.relative_to(base).parts:\n   current=current/part\n   if current.is_symlink():raise ValueError(\'专用采集目录不可使用符号链接\')\n   current.mkdir(exist_ok=True);os.chown(current,owner.pw_uid,owner.pw_gid);current.chmod(0o700)\n else:\n  root.mkdir(parents=True,exist_ok=True)\n  for current in [root,*reversed([p for p in path.parents if root in p.parents]),path]:\n   current.mkdir(parents=True,exist_ok=True);os.chown(current,owner.pw_uid,owner.pw_gid);current.chmod(0o700)\ndef read(path,default=None):\n try:return json.loads(Path(path).read_text(\'utf-8-sig\'))\n except FileNotFoundError:return {} if default is None else default\ndef settings():return read(ROOT/\'settings.json\')\ndef validate(v):\n if type(v.get(\'enabled\')) is not bool or not re.fullmatch(r\'(?:[01]\\d|2[0-3]):[0-5]\\d\',str(v.get(\'time\',\'\'))):raise ValueError(\'请选择有效的北京时间和定时开关\')\n questions=v.get(\'questions\')\n if not isinstance(questions,list) or not 1<=len(questions)<=100 or any(not isinstance(q,str) or not q.strip() or len(q)>2000 or \'\\n\' in q for q in questions):raise ValueError(\'每行一个问题，最多100题\')\n questions=[q.strip() for q in questions]\n if len(set(questions))!=len(questions):raise ValueError(\'问题有重复，请先去重\')\n return {\'enabled\':v[\'enabled\'],\'time\':v[\'time\'],\'questions\':questions}\ndef save(value):\n from geo_source_cards.runtime import process_lock\n value=validate(value)\n with process_lock(ROOT/\'settings.lock\',blocking=True):\n  old=settings()\n  if value[\'time\']==read(GEO/\'daily_plan.json\').get(\'time\'):raise ValueError(\'请与主GEO每日开始时间错开\')\n  atomic_json(ROOT/\'settings.json\',{**old,**value,\'updated_at\':time.time()})\n return {\'saved\':True,\'message\':\'创作专用采集设置已保存；正在执行的当日问题保持原配置\'}\ndef control(action,store_root=None,day=None):\n from geo_source_cards.runtime import process_lock\n root=Path(store_root) if store_root is not None else ROOT\n with process_lock(root/\'settings.lock\',blocking=True):\n  cfg=read(root/\'settings.json\')\n  if action==\'resume\':\n   for path in (root/\'days\').glob(\'*/blocked-*.json\'):\n    block=read(path)\n    session=read(GEO/\'deepseek_app_session.json\') if read(GEO/\'deepseek_backend.json\').get(\'backend\')==\'android\' else read(GEO/\'profiles/deepseek/geo-session-health.json\')\n    if block.get(\'kind\')==\'login_required\' and session.get(\'last_checkpoint\',0)<=block.get(\'at\',0):raise ValueError(\'请先在GEO采集页完成DeepSeek登录，再继续专用采集\')\n   for path in (root/\'days\').glob(\'*/blocked-*.json\'):path.unlink()\n  if day is None:cfg[\'paused\']=action==\'pause\'\n  else:\n   cfg[\'paused_day\']=day if action==\'pause\' else \'\'\n   if action==\'resume\':\n    cfg[\'paused\']=False\n    if day<datetime.now(ZONE).date().isoformat():cfg[\'requested_day\']=day\n  atomic_json(root/\'settings.json\',cfg)\n return {\'paused\':action==\'pause\'}\ndef records(day,question,channels,store_root=None):\n if not re.fullmatch(r\'\\d{4}-\\d{2}-\\d{2}\',day) or not set(channels)<=set(CHANNELS):raise ValueError(\'素材日期或通道不正确\')\n root=Path(store_root) if store_root is not None else ROOT\n paths=list((LEGACY/\'captures\'/day).glob(\'*/observations.jsonl\')) if root==ROOT else []\n paths+=list((root/\'days\'/day).glob(\'*/results.jsonl\'))\n paths+=list((root/\'supplements\'/day).glob(\'*/round-*/days/\'+day+\'/*/results.jsonl\'))\n rows=[];seen=set()\n for path in paths:\n  # JSONL records end at LF; Unicode separators inside JSON strings are data.\n  for line in path.read_text(\'utf-8-sig\').split(\'\\n\'):\n   if not line.strip():continue\n   row=json.loads(line)\n   if row.get(\'question\')!=question or row.get(\'model\') not in channels or row.get(\'body_capture_complete\') is False or row.get(\'availability\') in {\'supplement_unavailable\',\'no_card\'}:continue\n   identity=(row.get(\'model\'),row.get(\'task_id\') or row.get(\'url\'),row.get(\'captured_at\'))\n   if identity in seen:continue\n   seen.add(identity);rows.append(row)\n return rows\ndef catalog():\n dates=set()\n for base in (LEGACY/\'captures\',ROOT/\'days\'):\n  if base.exists():dates.update(p.name for p in base.iterdir() if p.is_dir() and re.fullmatch(r\'\\d{4}-\\d{2}-\\d{2}\',p.name))\n return {\'dates\':sorted(dates,reverse=True),\'questions\':settings().get(\'questions\',[]),\'channels\':[{\'id\':k,\'name\':v} for k,v in CHANNELS.items()]}\ndef progress(day,store_root=None):\n root=Path(store_root) if store_root is not None else ROOT\n result=[]\n for model,label in CHANNELS.items():\n  dbpath=root/\'days\'/day/model/\'collector/tasks.sqlite\';counts={};missing=[]\n  if dbpath.exists():\n   with sqlite3.connect(dbpath.as_uri()+\'?mode=ro\',uri=True) as db:\n    counts=dict(db.execute(\'select state,count(*) from captures group by state\'))\n    missing=[{\'question\':q,\'reason\':\'未出现AI卡片\' if \'card is still missing\' in (e or \'\') else \'缺少来源链接\' if \'source links are missing\' in (e or \'\') else \'多次读取后仍不完整\'} for q,e in db.execute("select question,error from captures where state=\'failed_deferred\'")]\n  recovery=read(dbpath.parent/\'search_recovery.json\') if any(s!=\'completed\' and n for s,n in counts.items()) else {}\n  recovery={k:recovery[k] for k in (\'status\',\'kind\',\'streak\',\'cooldown_until\',\'blocked\') if k in recovery}\n  result.append({\'id\':model,\'name\':label,\'completed\':counts.get(\'completed\',0),\'failed\':counts.get(\'failed_deferred\',0),\'settled\':counts.get(\'completed\',0)+counts.get(\'failed_deferred\',0),\'missing\':missing,\'counts\':counts,\'recovery\':recovery,\'blocked\':read(root/\'days\'/day/(\'blocked-\'+model+\'.json\')),\'error\':read(root/\'days\'/day/(\'error-\'+model+\'.json\'))})\n return result\ndef status():\n cfg=settings();now=datetime.now(ZONE);day=now.date().isoformat()\n candidate=datetime.combine(max(now.date(),datetime.strptime(cfg.get(\'start_date\',day),\'%Y-%m-%d\').date()),datetime.strptime(cfg.get(\'time\',\'01:00\'),\'%H:%M\').time(),ZONE)\n if candidate<=now:candidate+=timedelta(days=1)\n return {\'settings\':cfg,\'next_run\':candidate.isoformat() if cfg.get(\'enabled\') else None,\'health\':read(ROOT/\'health.json\'),\'progress\':progress(day),\'storage\':\'创作中心独立素材库\',\'geo_ingest_enabled\':False}\n\ndef dedicated_search(model):\n cfg=settings()\n return model in {\'baidu_ai\',\'wenxin_card\'} and cfg.get(\'search_pool\',\'creation_only\' if cfg.get(\'studio_plan\') else \'\')==\'creation_only\' and read(CONTENT_BASE/\'creation_search_pool.json\').get(\'enabled\') is True\n\ndef supplement_origin(root):\n value=os.environ.get(\'GEO_CREATION_SUPPLEMENT_ORIGIN\')\n if not value:return Path(root)\n origin=Path(value).resolve();root=Path(root).resolve()\n if origin.parent!=CONTENT_BASE/\'studio/capture\' or not origin.name.startswith(\'plan-\') or origin/\'supplements\' not in root.parents:raise ValueError(\'Invalid supplemental capture origin\')\n return origin\n\ndef search_resources(model):\n if dedicated_search(model):\n  # Each plan/channel already owns a persistent browser profile. Match its lock\n  # and rate state to that identity instead of serializing every plan together.\n  resource=supplement_origin(ROOT)/\'profiles/search\'/model\n  return {\'lock\':resource/\'browser.lock\',\'rate\':resource/\'last_search.json\',\'dedicated\':True}\n return {\'lock\':GEO/\'search_browser.lock\',\'rate\':GEO/\'search_last_start.json\',\'dedicated\':False}\n\ndef conflict(now,model,geo_plan,busy,*,dedicated=False):\n """No new question while main monitoring runs or its next window is close."""\n if dedicated and model in {\'baidu_ai\',\'wenxin_card\'}:return None\n if busy:return \'waiting_for_geo\'\n if not geo_plan.get(\'enabled\'):return None\n start=datetime.combine(now.date(),datetime.strptime(geo_plan.get(\'time\',\'05:00\'),\'%H:%M\').time(),ZONE)\n if 0<=(now-start).total_seconds()<300:return \'waiting_for_geo_window\'\n if start<=now:start+=timedelta(days=1)\n margin=1800 if model==\'deepseek\' else 300\n return \'waiting_for_geo_window\' if (start-now).total_seconds()<margin else None\n\nclass InsufficientMaterials(ValueError):\n pass\n\ndef prepare(root,job):\n """Fetch referenced public articles into a private job cache, no GEO writes."""\n from geo_source_cards.editorial_pipeline import prepare as fetch\n from geo_source_cards.article_fetch import MediaScopedFetcher,ScraplingArticleFetcher\n from geo_source_cards.daily_editorial import DEFAULT_MEDIA,prepare_day\n from geo_source_cards.pipeline_control import ensure_running\n input_path=root/\'private_observations.jsonl\';out=root/(\'private_source_analysis\'+(\'-supplement-\'+str(job[\'supplement_attempt\']) if job.get(\'supplement_attempt\') else \'\'))\n from .source_cache import SourceCache\n from . import runtime\n cache=SourceCache(root,ScraplingArticleFetcher(),content_db=runtime.CONTENT)\n wrapped=MediaScopedFetcher(cache,DEFAULT_MEDIA)\n sources={s[\'url\'] for row in read_lines(input_path) for s in row.get(\'sources\',[])}\n class ObservedFetcher:\n  def __init__(self):self.completed=0\n  def __call__(self,url):\n   atomic_json(root/\'material_preparation.json\',{\'at\':time.time(),\'phase\':\'fetching_sources\',\'processed\':self.completed,\'total\':len(sources),\'current_url\':url})\n   result=wrapped(url);self.completed+=1\n   atomic_json(root/\'material_preparation.json\',{\'at\':time.time(),\'phase\':\'fetching_sources\',\'processed\':self.completed,\'total\':len(sources),\'last_status\':result.get(\'status\'),\'cache_hits\':cache.hits,\'failure_kind\':result.get(\'failure_kind\')})\n   return result\n fetch(input_path,root/\'product.json\',out,job[\'date\'],fetcher=ObservedFetcher())\n ensure_running(root)\n rows=[json.loads(line) for line in (out/\'articles.jsonl\').read_text().split(\'\\n\') if line.strip()]\n from .owned_sources import exclude_owned\n rows,owned=exclude_owned(rows,root)\n from geo_source_cards.source_scope import anchors,evaluate\n terms=anchors([job.get(\'question\',\'\')],read(root/\'product.json\'))\n scoped=[];off_topic=[]\n for row in rows:\n  sources=[]\n  for source in row.get(\'sources\',[]):\n   scope=evaluate(source,terms)\n   if scope[\'status\']==\'off_topic\':off_topic.append({\'url\':source[\'url\'],\'title\':source.get(\'article\',{}).get(\'title\') or source.get(\'title\',\'\'),\'scope\':scope})\n   else:sources.append(source)\n  if sources:scoped.append({**row,\'sources\':sources})\n rows=scoped\n atomic_json(root/\'off_topic_source_exclusions.json\',{\'sources\':off_topic,\'excluded_count\':len(off_topic)})\n filtered,full=usable_source_rows(rows)\n minimum=1 if read(root/\'rewrite_policy.json\').get(\'workflow\')==\'rewrite-v2\' else 3\n if full<minimum:raise InsufficientMaterials((\'已排除\'+str(len(owned))+\'条自有产品信源；\' if owned else \'\')+(\'已排除\'+str(len(off_topic))+\'条跑题来源；\' if off_topic else \'\')+shortfall_message(rows,full,minimum))\n atomic_write(root/\'geo_articles.jsonl\',\'\'.join(json.dumps(row,ensure_ascii=False)+\'\\n\' for row in filtered))\n if job.get(\'article_target\'):atomic_json(root/\'article_goal.json\',{\'target\':job[\'article_target\'],\'prefer_genres\':[\'排行类\',\'科普类\'],\'genre_targets\':job.get(\'genre_targets\',{})})\n result=prepare_day(root,root/\'geo_articles.jsonl\',root/\'product.json\',job[\'date\'],max_per_category=max(job[\'max_per_category\'],job.get(\'article_target\',0)))\n job.update(preparation=\'ready\',material_counts={\'geo_observations\':0,\'private_observations\':len(rows),\'full_articles\':full},prepared=result)\n atomic_json(root/\'job.json\',job)\n atomic_json(root/\'material_preparation.json\',{\'at\':time.time(),\'phase\':\'ready\',\'full_article_records\':full})\n return job\n\ndef shortfall_message(rows,full,minimum=3):\n from geo_source_cards.article_quality import normalize\n articles=[s.get(\'article\',{}) for r in rows for s in r.get(\'sources\',[])]\n outside=sum(a.get(\'status\')==\'unregistered_media\' for a in articles)\n incomplete=sum(a.get(\'status\')!=\'unregistered_media\' and normalize(a).get(\'status\')!=\'fetched\' for a in articles)\n details=[]\n if outside:details.append(str(outside)+\'条来源不在当前允许的媒体范围内\')\n if incomplete:details.append(str(incomplete)+\'条未取得合格完整正文\')\n from .source_cache import failure_kind\n failed={s.get(\'url\'):s.get(\'article\',{}) for r in rows for s in r.get(\'sources\',[]) if s.get(\'article\',{}).get(\'status\')==\'failed\'}\n for kind,label in [(\'dns\',\'链接域名解析暂时失败\'),(\'verification\',\'来源网站要求访问验证\'),(\'not_found\',\'原文链接已失效\')]:\n  count=sum(failure_kind(a)==kind for a in failed.values())\n  if count:details.append(label+str(count)+\'条\')\n return \'可用完整正文\'+str(full)+\'篇，至少需要\'+str(minimum)+\'篇\'+(\'（\'+\'；\'.join(details)+\'）\' if details else \'\')+\'；需补充有效来源\'\n\ndef usable_source_rows(rows):\n from geo_source_cards.article_quality import normalize\n filtered=[];full=0;seen=set()\n for row in rows:\n  sources=[]\n  for source in row.get(\'sources\',[]):\n   article=normalize(source.get(\'article\',{}))\n   url=article.get(\'final_url\') or source.get(\'url\')\n   if article.get(\'status\')==\'fetched\' and url not in seen:\n    seen.add(url);sources.append({**source,\'article\':article})\n  if sources:filtered.append({**row,\'sources\':sources});full+=len(sources)\n return filtered,full\n\ndef read_lines(path):return [json.loads(line) for line in Path(path).read_text().split(\'\\n\') if line.strip()]\n\ndef main_busy():\n with sqlite3.connect((GEO/\'panel/control.sqlite\').as_uri()+\'?mode=ro\',uri=True) as db:services=[r[0] for r in db.execute(\'select service from jobs where batch in (select current_batch from settings)\')]\n for service in services:\n  value=subprocess.run([\'systemctl\',\'is-active\',service],capture_output=True,text=True,timeout=8).stdout.strip()\n  if value in {\'active\',\'activating\',\'deactivating\',\'reloading\'}:return True\n return False\n\ndef next_day(cfg,today,now=None):\n if cfg.get(\'requested_day\'):return cfg[\'requested_day\']\n if cfg.get(\'day_policy\')==\'today_first\' and cfg.get(\'frequency\')==\'daily\' and today>=cfg[\'start_date\'] and (now or datetime.now(ZONE)).strftime(\'%H:%M\')>=cfg.get(\'time\',\'01:00\'):return today\n for path in sorted((ROOT/\'days\').glob(\'*/config.json\')):\n  day=path.parent.name\n  if day>today or cfg.get(\'paused_day\')==day:continue\n  plan=read(path);counts={v[\'id\']:v.get(\'settled\',v[\'completed\']) for v in progress(day)}\n  if any(counts[m]<len(plan[\'questions\'])*plan.get(\'rounds\',1) for m in plan.get(\'channels\',CHANNELS)):return day\n return cfg[\'start_date\'] if cfg.get(\'frequency\')==\'once\' else today\n\ndef capture_snapshot(target,cfg,owner):\n """Keep immutable contents, granting the collector group read-only access."""\n path=Path(target)/\'config.json\'\n if not path.exists():atomic_json(path,cfg)\n os.chown(path,-1,owner.pw_gid);path.chmod(0o640)\n\ndef run():\n """One-question subprocesses release shared account locks at safe boundaries."""\n from geo_source_cards.runtime import process_lock\n import pwd\n owner=pwd.getpwnam(\'user\');children={};attempts={}\n def private_dir(path):collector_directory(path,owner)\n with process_lock(ROOT/\'worker.lock\'):\n  while True:\n   now=datetime.now(ZONE);cfg=settings();day=next_day(cfg,now.date().isoformat(),now);health={\'at\':time.time(),\'day\':day,\'status\':\'scheduled\'}\n   for model,child in list(children.items()):\n    process,log,child_day=child\n    if process.poll() is None:continue\n    code=process.returncode;log.close();del children[model]\n    if code==77:atomic_json(ROOT/\'days\'/child_day/(\'blocked-\'+model+\'.json\'),{\'at\':time.time(),\'kind\':\'login_required\' if model==\'deepseek\' else \'verification_required\'})\n    elif code:\n     attempts[model]=time.time()+(5 if code==75 and model!=\'deepseek\' else 60)\n     if code!=75:atomic_json(ROOT/\'days\'/child_day/(\'error-\'+model+\'.json\'),{\'at\':time.time(),\'exit_code\':code,\'retry_at\':attempts[model],\'message\':\'采集进程异常退出，正在自动重试\'})\n    else:(ROOT/\'days\'/child_day/(\'error-\'+model+\'.json\')).unlink(missing_ok=True)\n   try:\n    due=day<=now.date().isoformat() and ((ROOT/\'days\'/day/\'config.json\').exists() or (cfg.get(\'enabled\') and day>=cfg.get(\'start_date\',day) and (day<now.date().isoformat() or now.strftime(\'%H:%M\')>=cfg.get(\'time\',\'01:00\'))))\n    paused=cfg.get(\'paused\') or cfg.get(\'paused_day\')==day\n    if due and not paused:\n     target=ROOT/\'days\'/day;private_dir(target)\n     capture_snapshot(target,cfg,owner)\n     plan=read(target/\'config.json\');questions=plan[\'questions\'];rounds=plan.get(\'rounds\',1);channels=plan.get(\'channels\',list(CHANNELS));progress_by={v[\'id\']:v for v in progress(day)}\n     busy=main_busy();health[\'status\']=\'running\';health[\'geo_ingest_enabled\']=False\n     health[\'search_resource_pool\']=\'creation_only\' if dedicated_search(\'baidu_ai\') else \'shared_geo\'\n     for model in CHANNELS:\n      if model not in channels or model in children or progress_by[model].get(\'settled\',progress_by[model][\'completed\'])>=len(questions)*rounds:continue\n      if progress_by[model][\'blocked\']:\n       block=progress_by[model][\'blocked\'];session=read(GEO/\'deepseek_app_session.json\')\n       if (model==\'deepseek\' and read(GEO/\'deepseek_backend.json\').get(\'backend\')==\'android\'\n           and block.get(\'kind\')==\'login_required\' and session.get(\'status\')==\'ready\'\n           and session.get(\'last_checkpoint\',0)>block.get(\'at\',0)):\n        (target/(\'blocked-\'+model+\'.json\')).unlink(missing_ok=True);progress_by[model][\'blocked\']={}\n       else:health[\'status\']=\'waiting_login_or_verification\';continue\n      resources=search_resources(model)\n      reason=conflict(now,model,read(GEO/\'daily_plan.json\'),busy,dedicated=resources[\'dedicated\'])\n      if reason:health[\'status\']=reason;continue\n      if attempts.get(model,0)>time.time():continue\n      if model!=\'deepseek\' and any(m!=\'deepseek\' for m in children):continue\n      lane=target/model;private_dir(lane);runtime=lane/\'collector\';private_dir(runtime)\n      qfile=lane/\'questions.txt\';atomic_write(qfile,\'\\n\'.join(questions)+\'\\n\');os.chown(qfile,owner.pw_uid,owner.pw_gid)\n      env={**os.environ,\'PYTHONPATH\':\'\',\'GEO_COLLECTOR_RUNTIME\':str(runtime),\'GEO_DEEPSEEK_PROFILE_DIR\':str(GEO/\'profiles/deepseek\'),\'GEO_DEEPSEEK_PORT\':\'9514\',\'GEO_DEEPSEEK_RATE_STATE\':str(GEO/\'deepseek_last_send.json\'),\'GEO_SEARCH_RATE_STATE\':str(resources[\'rate\']),\'GEO_UNATTENDED\':\'1\'}\n      env.pop(\'GEO_PIPELINE_ROOT\',None)\n      env[\'GEO_DEEPSEEK_SEED_ROOT\']=str(GEO/\'batches\')\n      lock=GEO/\'deepseek_account.lock\' if model==\'deepseek\' else resources[\'lock\']\n      command=[\'/usr/sbin/runuser\',\'-u\',\'user\',\'--\',\'/usr/bin/flock\',\'-n\',str(lock),\'/opt/monitor/geo-capture/venv/bin/python\',\'-m\',\'geo_source_cards.cli\',\'--model\',model,\'--runtime-dir\',str(runtime),\'--batch\',\'creation-material-\'+day+\'-\'+model,\'--questions-file\',str(qfile),\'--rounds\',str(rounds),\'--output\',str(lane/\'results.jsonl\'),\'--require-sources\',\'--require-complete-sources\',\'--min-deepseek-interval\',\'600\',\'--min-search-interval\',\'60\',\'--max-new-captures\',\'1\']\n      if resources[\'dedicated\']:\n       if supplement_origin(ROOT)==ROOT:private_dir(resources[\'lock\'].parent)\n       elif not resources[\'lock\'].parent.is_dir():raise ValueError(\'Original capture profile has not been initialized\')\n       adapter=command.index(\'geo_source_cards.cli\');command[adapter-1:adapter+1]=[\'/opt/monitor/geo-content/bin/search_capture.py\']\n       command=command[:4]+[\'/opt/monitor/geo-content/bin/creation-runner\',\'capture\',str(SEARCH_POOL/\'slots\'),str(resources[\'lock\']),\'--\']+command[7:]\n      if model!=\'deepseek\':command+=[\'--bounded-search-recovery\']\n      if model==\'baidu_ai\':command+=[\'--optional-baidu\']\n      if model==\'deepseek\' and read(GEO/\'deepseek_backend.json\').get(\'backend\')==\'android\':\n       command=[\'/home/user/redroid-doubao/worker-venv/bin/python\',\'-B\',\'/home/user/redroid-deepseek/code/private_capture.py\',\'--lane\',str(lane),\'--batch\',\'creation-material-\'+day+\'-\'+model,\'--rounds\',str(rounds)]\n      if model==\'deepseek\' and read(Path(\'/opt/monitor/geo-deepseek-browser-test/production.json\')).get(\'enabled\') is True:\n       command=[\'/home/user/geo-editorial/venv/bin/python\',\'-B\',\'-m\',\'creation.browser_capture\',\'--lane\',str(lane),\'--batch\',\'creation-material-\'+day+\'-\'+model,\'--rounds\',str(rounds)]\n       env[\'PYTHONPATH\']=\'/opt/monitor/geo-content:/opt/monitor/geo-content/engine\'\n      log=(lane/\'capture.log\').open(\'ab\');children[model]=(subprocess.Popen(command,env=env,stdout=log,stderr=subprocess.STDOUT),log,day)\n     if not children and any(attempts.get(m,0)>time.time() and read(target/(\'error-\'+m+\'.json\')) for m in channels):health[\'status\']=\'retrying\'\n     if not children and any(read(Path(str(search_resources(m)[\'lock\'])+\'.waiting.json\')) for m in channels if dedicated_search(m)):\n      health[\'status\']=\'waiting_capture_capacity\'\n     if all(progress_by[m].get(\'settled\',progress_by[m][\'completed\'])>=len(questions)*rounds for m in channels):\n      health[\'status\']=\'complete\'\n      if cfg.get(\'requested_day\'):\n       with process_lock(ROOT/\'settings.lock\',blocking=True):\n        latest=settings();latest.pop(\'requested_day\',None);atomic_json(ROOT/\'settings.json\',latest)\n    elif paused:health[\'status\']=\'pausing\' if children else \'paused\'\n    health[\'active_channels\']=list(children)\n   except Exception as error:health.update(status=\'retrying\',error_kind=type(error).__name__)\n   atomic_json(ROOT/\'health.json\',health);time.sleep(5)\n\nif __name__==\'__main__\':run()\n'}, 'creation/source_cache.py': {'source': 'geo-monitor-deploy/creation/source_cache.py', 'before': '6061f0af0f7f9049f5ba4ae6171dd69f0e8f0a538d893f58065015a8de17e70b', 'text': '"""Reuse public source reads across supplemental rounds of the same job.\n\nOwnership, topic, media and article quality checks still run after fetching.\nFailures remain failures and expire quickly so transient outages can recover.\n"""\nimport hashlib\nimport json\nimport time\nimport sqlite3\nfrom contextlib import closing\nfrom datetime import datetime\nfrom zoneinfo import ZoneInfo\nfrom pathlib import Path\n\nfrom geo_source_cards.runtime import atomic_json\n\n\ndef failure_kind(article):\n    errors = \' \'.join(str(a.get(\'error\', \'\')) for a in article.get(\'attempts\', []))\n    errors += \' \' + str(article.get(\'error\', \'\'))\n    errors = errors.lower()\n    if any(s in errors for s in (\'name resolution\', \'getaddrinfo\', \'name or service not known\')):\n        return \'dns\'\n    if any(s in errors for s in (\'verification\', \'access-denied\', \'access denied\')):\n        return \'verification\'\n    if \'http 404\' in errors or \'http 410\' in errors:\n        return \'not_found\'\n    return \'unavailable\'\n\n\nclass SourceCache:\n    def __init__(self, root, fetcher, clock=time.time, content_db=None):\n        self.root = Path(root)\n        self.fetcher = fetcher\n        self.clock = clock\n        self.directory = self.root / \'source_read_cache\'\n        self.hits = 0\n        self.content_db = Path(content_db) if content_db is not None else None\n\n    def shared_article(self, url):\n        """Read exact-URL verified GEO snapshots without extending their age."""\n        if self.content_db is None or not self.content_db.is_file():return None\n        from .source_adapter import article\n        from geo_source_cards.article_quality import normalize\n        try:\n            with closing(sqlite3.connect(self.content_db.resolve().as_uri()+\'?mode=ro\',uri=True,timeout=2)) as db:\n                db.row_factory=sqlite3.Row\n                row=db.execute(\'select * from source_content where url=?\',(url,)).fetchone()\n            if not row:return None\n            at=datetime.strptime(row[\'fetched_at\'],\'%Y-%m-%d %H:%M:%S\').replace(tzinfo=ZoneInfo(\'Asia/Shanghai\')).timestamp()\n            if not 0<=self.clock()-at<86400:return None\n            value=normalize(article(row,url))\n            if value.get(\'status\')!=\'fetched\':return None\n            return {**value,\'requested_url\':url,\'source_read_at\':at,\'fetched_at\':at,\n                    \'original_fetched_at\':row[\'fetched_at\'],\'reused_from\':\'geo_source_content_sqlite\'}\n        except (sqlite3.Error,OSError,ValueError,KeyError,TypeError):return None\n\n    def valid(self, path, url):\n        try:\n            article = json.loads(path.read_text(\'utf-8\'))\n            if article.get(\'requested_url\') != url:\n                return None\n            ttl = 86400 if article.get(\'status\') == \'fetched\' else {\n                \'dns\': 60, \'verification\': 900, \'not_found\': 3600,\n            }.get(article.get(\'failure_kind\'), 60)\n            if 0 <= self.clock() - float(article.get(\'source_read_at\', article.get(\'fetched_at\', 0))) < ttl:\n                return article\n        except (OSError, ValueError, TypeError, AttributeError):\n            pass\n        return None\n\n    def __call__(self, url):\n        key = hashlib.sha256(url.encode()).hexdigest() + \'.json\'\n        destination = self.directory / key\n        cached = self.valid(destination, url)\n        if cached is None or cached.get(\'status\')!=\'fetched\':\n            shared=self.shared_article(url)\n            if shared is not None:\n                cached=shared\n                atomic_json(destination,shared)\n        if cached is None:\n            # Older rounds already have successful exact-URL caches. Preserve\n            # their original timestamp; reading must never extend freshness.\n            for path in sorted(self.root.glob(\'private_source_analysis*/article_cache/\' + key),\n                               key=lambda p: p.stat().st_mtime, reverse=True):\n                candidate = self.valid(path, url)\n                if candidate and candidate.get(\'status\') == \'fetched\':\n                    cached = {**candidate, \'source_read_at\': candidate.get(\'source_read_at\', candidate[\'fetched_at\'])}\n                    atomic_json(destination, cached)\n                    break\n        if cached is not None:\n            self.hits += 1\n            return cached\n        article = {**self.fetcher(url), \'requested_url\': url, \'fetched_at\': self.clock(), \'source_read_at\': self.clock()}\n        if article.get(\'status\') == \'failed\':\n            article[\'failure_kind\'] = failure_kind(article)\n        atomic_json(destination, article)\n        return article\n'}, 'creation/runtime.py': {'source': 'geo-monitor-deploy/creation/runtime.py', 'before': '86eee7071a8462f3584ac38c401efd29792d76b8094940341ba4f9412fabf11d', 'text': '"""Durable GEO creation jobs, reusing the original evidence/review/Word engine."""\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport re\nimport sqlite3\nimport time\nimport uuid\nfrom contextlib import closing\n\nfrom geo_source_cards import daily_editorial, pipeline_control\nfrom geo_source_cards.api_budget import Budget,BudgetExceeded,ArticleBudgetExceeded\nfrom geo_source_cards.deepseek_api import DeepSeekClient\nfrom geo_source_cards.runtime import atomic_json, atomic_write, process_lock\nfrom . import source_adapter\nfrom .client import CreationClient\n\nBASE=Path(os.environ.get(\'GEO_CREATION_ROOT\',\'/opt/monitor/geo-content/runtime\'))\nSHARED=Path(\'/home/user/geo-editorial/runtime-api\')\nKEY=Path(\'/home/user/geo-editorial/secrets/deepseek.key\')\nCONTENT=Path(\'/opt/monitor/doubao_source_content.db\')\n\ndef read(path,default=None):\n    try:return json.loads(Path(path).read_text(\'utf-8-sig\'))\n    except FileNotFoundError:return {} if default is None else default\n\ndef digest(value):\n    return hashlib.sha256(json.dumps(value,ensure_ascii=False,sort_keys=True).encode()).hexdigest()\n\ndef db():\n    BASE.mkdir(parents=True,exist_ok=True)\n    conn=sqlite3.connect(BASE/\'operations.sqlite\',timeout=30)\n    try:\n        # Concurrent first uploads must not race while changing journal mode.\n        # This only serializes connection setup, not image processing/uploads.\n        with process_lock(BASE/\'operations-init.lock\',blocking=True):\n            if conn.execute(\'pragma journal_mode\').fetchone()[0].lower()!=\'wal\':\n                conn.execute(\'pragma journal_mode=WAL\')\n            conn.execute(\'pragma synchronous=FULL\')\n            conn.execute(\'create table if not exists operations(id text primary key,payload_hash text,result text)\')\n        return conn\n    except Exception:\n        conn.close()\n        raise\n\ndef job_root(identity):\n    if not re.fullmatch(r\'creation-[0-9]+-[a-f0-9]{8}\',identity):raise ValueError(\'任务编号不正确\')\n    path=BASE/\'runs\'/identity\n    if not (path/\'job.json\').is_file():raise ValueError(\'任务不存在\')\n    return path\n\nclass SharedBudget(Budget):\n    def __init__(self,root):\n        super().__init__(SHARED)\n        self.root=Path(root)  # pause/call logs belong to this job; ledger stays canonical.\n\n    def remaining(self,meta,stage):\n        job=read(self.root/\'job.json\');limits=job.get(\'budget_limits\') or {}\n        if not limits:return None\n        from datetime import datetime\n        from geo_source_cards.api_budget import BEIJING\n        config=pipeline_control.settings(SHARED);scope=job.get(\'studio_plan_id\') or job[\'job_id\']\n        category=meta.get(\'category\',\'\');article=str(meta.get(\'number\',0))\n        try:\n            joined=\'select coalesce(sum(coalesce(c.charged,c.reserved)),0) from costs c join studio_cost_scopes s on s.id=c.id where \'\n            daily=self.db.execute(\'select coalesce(sum(coalesce(charged,reserved)),0) from costs where date=?\',(datetime.now(BEIJING).date().isoformat(),)).fetchone()[0]\n            used=self.db.execute(joined+\'s.scope=? and s.task_day=?\',(scope,job[\'date\'])).fetchone()[0]\n            per=self.db.execute(joined+"s.job=? and (c.category=\'\' or (c.category=? and (c.article=\'shared\' or c.article=?)))",(job[\'job_id\'],category,article)).fetchone()[0]\n        except sqlite3.OperationalError:return None\n        return max(0,min(config[\'daily_budget_cny\']-daily,limits[\'task_budget_cny\']-used,\n                         min(limits[\'article_budget_cny\'],config[\'article_budget_cny\'])-per))\n\n    def reserve(self,payload,directory,meta,stage):\n        job=read(self.root/\'job.json\');limits=job.get(\'budget_limits\') or {}\n        if not limits:return super().reserve(payload,directory,meta,stage)\n        from datetime import datetime\n        from geo_source_cards.api_budget import PRICE_DATE,INPUT_MISS,OUTPUT,BEIJING\n        if (datetime.now(BEIJING).date()-datetime.fromisoformat(PRICE_DATE).date()).days>30:\n            raise BudgetExceeded(\'Budget price version requires review\')\n        upper=(len(json.dumps(payload[\'messages\'],ensure_ascii=False).encode(\'utf8\'))+256)*INPUT_MISS/1000000+payload[\'max_tokens\']*OUTPUT/1000000\n        config=pipeline_control.settings(SHARED);identity=hashlib.sha256(str(Path(directory).resolve()).encode()).hexdigest()\n        scope=job.get(\'studio_plan_id\') or job[\'job_id\'];category=meta.get(\'category\',\'\')\n        article=\'shared\' if stage==\'taxonomy\' or stage==\'research\' and meta.get(\'cost_scope\')!=\'article\' else str(meta.get(\'number\',0))\n        date=datetime.now(BEIJING).date().isoformat()\n        self.db.execute(\'create table if not exists studio_cost_scopes(id text primary key,scope text,task_day text,job text)\')\n        self.db.execute(\'begin immediate\')\n        try:\n            previous=self.db.execute(\'select state,charged from costs where id=?\',(identity,)).fetchone()\n            if previous:\n                if previous[\'state\']==\'settled\' and previous[\'charged\']==0:\n                    archived=identity+\'-rejected-\'+str(time.time_ns())\n                    self.db.execute(\'update costs set id=? where id=?\',(archived,identity))\n                    self.db.execute(\'update studio_cost_scopes set id=? where id=?\',(archived,identity))\n                else:raise BudgetExceeded(\'Existing reservation requires execution review\')\n            total=\'select coalesce(sum(coalesce(charged,reserved)),0) from costs where \'\n            daily=self.db.execute(total+\'date=?\',(date,)).fetchone()[0]\n            joined=\'select coalesce(sum(coalesce(c.charged,c.reserved)),0) from costs c join studio_cost_scopes s on s.id=c.id where \'\n            used=self.db.execute(joined+\'s.scope=? and s.task_day=?\',(scope,job[\'date\'])).fetchone()[0]\n            per=self.db.execute(joined+"s.job=? and (c.category=\'\' or (c.category=? and (c.article=\'shared\' or c.article=?)))",(job[\'job_id\'],category,article)).fetchone()[0]\n            if daily+upper>config[\'daily_budget_cny\']+1e-9 or used+upper>limits[\'task_budget_cny\']+1e-9:\n                raise BudgetExceeded(\'Creation budget exhausted; request was not sent\')\n            if per+upper>min(limits[\'article_budget_cny\'],config[\'article_budget_cny\'])+1e-9:\n                raise ArticleBudgetExceeded(\'Article budget exhausted; request was not sent\')\n            self.db.execute(\'insert into costs values(?,?,?,?,?,?,?,?,?,?,?,?)\',(identity,date,meta[\'date\'],category,article,stage,0,\'reserved\',upper,None,None,time.time()))\n            self.db.execute(\'insert into studio_cost_scopes values(?,?,?,?)\',(identity,scope,job[\'date\'],job[\'job_id\']))\n            self.db.commit()\n        except BaseException:\n            self.db.rollback();raise\n        return identity\n\n\ndef balance():return CreationClient(KEY).balance()\n\ndef resume(root,*,check_balance=True,allow_http_recovery=False):\n    from . import recovery\n    assert_job_controllable(root)\n    if check_balance:\n        checked=balance()\n        if not checked[\'is_available\']:raise ValueError(\'DeepSeek API余额不可用\')\n    replacement=recovery.recover_http_failure(root) if allow_http_recovery else None\n    with process_lock(root/\'control.lock\',blocking=True):\n        old=pipeline_control.state(root)\n        # Do not replay a request with unknown delivery, even after operator resume.\n        if not recovery.safe_original(root):\n            raise ValueError(\'存在发送结果未知的API请求，须先核对；不会自动重发\')\n        atomic_json(root/\'environment_check.json\',{\'checked_epoch\':time.time(),\'ready\':True,\n            \'control_revision\':old.get(\'revision\',0),\'source\':\'GEO existing data + DeepSeek API only\'})\n        atomic_json(root/\'control.json\',{\'paused\':False,\'revision\':old.get(\'revision\',0)+1,\n            \'resumed_epoch\':time.time()})\n        recovery.succeeded(root)\n    return {\'resumed\':True,**({\'replacement_ticket\':replacement} if replacement else {})}\n\ndef create(payload):\n    day=payload.get(\'date\',\'\');question=payload.get(\'question\',\'\')\n    channels=payload.get(\'channels\',[\'deepseek\',\'wenxin_card\',\'baidu_ai\'])\n    limit=payload.get(\'max_per_category\',10)\n    if type(limit) is not int or not 1<=limit<=10:raise ValueError(\'每类篇数须为1至10\')\n    product=payload.get(\'product\') or read(SHARED/\'product.json\')\n    if not isinstance(product,dict) or not product.get(\'name\') or not isinstance(product.get(\'facts\'),list):\n        raise ValueError(\'请填写原有格式的产品事实资料\')\n    private=payload.get(\'material_source\')==\'dedicated\'\n    studio_plan=payload.get(\'studio_plan_id\')\n    if studio_plan:\n        from . import studio\n        studio.plan(studio_plan) # Reject stale scheduler snapshots after deletion.\n        snapshot=read(studio.day_path(studio_plan,day)).get(\'plan\') or studio.plan(studio_plan)\n        product=studio.complete_product_source(product,snapshot.get(\'product_id\'),snapshot.get(\'product_version\'))\n    pooled_questions=payload.get(\'questions\')\n    article_target=payload.get(\'article_target\',0)\n    if pooled_questions is not None:\n        if not private or not studio_plan or not isinstance(pooled_questions,list) or not pooled_questions or len(pooled_questions)>100 or any(not isinstance(q,str) or not q.strip() for q in pooled_questions) or len(set(pooled_questions))!=len(pooled_questions):raise ValueError(\'任务汇总问题不正确\')\n        if type(article_target) is not int or not 1<=article_target<=100:raise ValueError(\'请设置1至100篇的任务成稿目标\')\n    if private:\n        from . import materials\n        if studio_plan:\n            from . import studio\n            if read(studio.day_path(studio_plan,day)).get(\'paused\'):raise ValueError(\'当日创作任务已暂停\')\n            if pooled_questions is not None:\n                confirmed=read(studio.day_path(studio_plan,day)).get(\'plan\') or studio.plan(studio_plan)\n                if pooled_questions!=confirmed[\'questions\'] or article_target!=confirmed.get(\'article_target\'):raise ValueError(\'汇总须使用当天已确认的问题和篇数\')\n                rows=[];seen=set()\n                for q in pooled_questions:\n                    for row in materials.records(day,q,channels,store_root=studio.capture_root(studio_plan)):\n                        key=digest(row)\n                        if key not in seen:rows.append(row);seen.add(key)\n            else:rows=materials.records(day,question,channels,store_root=studio.capture_root(studio_plan))\n        else:rows=materials.records(day,question,channels)\n        if not rows:raise ValueError(\'所选专用问题尚无采集素材，请选择已有素材日期或等待凌晨专用采集\')\n        material={\'observations\':rows,\'counts\':{\'private_observations\':len(rows),\'full_articles\':0},\'source\':\'creation_only\'}\n    else:\n        rows=source_adapter.observations(day,question,channels)\n        material=source_adapter.snapshot(rows,CONTENT)\n        if material[\'counts\'][\'full_articles\']<3:raise ValueError(\'该日期问题不足3篇已通过完整正文校验的国内媒体素材，请更换日期或等待正文入库\')\n    inputs={\'workflow\':\'rewrite-v2\',\'date\':day,\'question\':question,\'channels\':sorted(channels),\'max_per_category\':limit,\n        \'product\':product,\'observations\':material[\'observations\']}\n    if private:inputs[\'material_source\']=\'dedicated\'\n    if studio_plan:inputs[\'studio_plan_id\']=studio_plan\n    if pooled_questions is not None:\n        from geo_source_cards.article_allocation import validate_quotas\n        inputs.update(questions=pooled_questions,article_target=article_target,genre_targets=validate_quotas(payload.get(\'genre_targets\'),article_target))\n    if payload.get(\'budget_limits\'):\n        import math\n        limits=payload[\'budget_limits\'];shared=pipeline_control.settings(SHARED)\n        if not isinstance(limits,dict) or set(limits)!={\'article_budget_cny\',\'task_budget_cny\'} or any(type(v) not in (int,float) or not math.isfinite(v) or v<=0 for v in limits.values()) or limits[\'article_budget_cny\']>shared[\'article_budget_cny\'] or limits[\'task_budget_cny\']>shared[\'daily_budget_cny\']:\n            raise ValueError(\'任务预算设置不正确或超过共享限额\')\n        inputs[\'budget_limits\']=limits\n    fingerprint=digest(inputs)\n    for path in sorted((BASE/\'runs\').glob(\'*/job.json\')):\n        previous=read(path)\n        if previous.get(\'input_sha256\')==fingerprint:return {\'job_id\':previous[\'job_id\'],\'reused\':True}\n    identity=\'creation-\'+str(int(time.time()))+\'-\'+uuid.uuid4().hex[:8]\n    root=BASE/\'runs\'/identity;root.mkdir(parents=True,exist_ok=False)\n    defaults=read(BASE/\'rewrite_defaults.json\')\n    automatic=defaults.get(\'skeleton_review\')==\'automatic\' and isinstance(defaults.get(\'authorization\'),str) and defaults[\'authorization\'].strip()\n    atomic_json(root/\'rewrite_policy.json\',{\'workflow\':\'rewrite-v2\',\'cache_dir\':str(BASE/\'rewrite_cache\'),\'max_rewrites\':1,\n        \'review_policy\':\'evidence-v3\',\'max_targeted_repairs\':0,\'article_delivery\':\'direct\',\n        **({\'skeleton_review\':\'automatic\',\'authorization\':defaults[\'authorization\']} if automatic else {})})\n    atomic_json(root/\'control.json\',{\'paused\':True,\'revision\':0,\'reason\':\'preparing\',\'message\':\'准备GEO素材\'})\n    atomic_json(root/\'settings.json\',{**pipeline_control.settings(SHARED),\'max_per_category\':limit})\n    atomic_json(root/\'product.json\',product)\n    atomic_json(root/\'geo_material_manifest.json\',material)\n    atomic_write(root/\'geo_articles.jsonl\',\'\'.join(json.dumps(r,ensure_ascii=False)+\'\\n\' for r in material[\'observations\']))\n    if private:\n        atomic_write(root/\'private_observations.jsonl\',\'\'.join(json.dumps(r,ensure_ascii=False)+\'\\n\' for r in rows))\n        prepared={\'status\':\'waiting_material_preparation\'}\n    else:\n        from .owned_sources import exclude_owned\n        clean,_=exclude_owned(material[\'observations\'],root)\n        atomic_write(root/\'geo_articles.jsonl\',\'\'.join(json.dumps(r,ensure_ascii=False)+\'\\n\' for r in clean))\n        prepared=daily_editorial.prepare_day(root,root/\'geo_articles.jsonl\',root/\'product.json\',day,max_per_category=limit)\n    atomic_json(root/\'job.json\',{\'workflow\':\'rewrite-v2\',\'job_id\':identity,\'created_at\':time.time(),\'input_sha256\':fingerprint,\n        \'date\':day,\'question\':question,\'channels\':sorted(channels),\'max_per_category\':limit,\n        \'material_counts\':material[\'counts\'],\'platform_questions_sent\':0,\'prepared\':prepared,\n        \'material_source\':\'dedicated\' if private else \'geo\',\'studio_plan_id\':studio_plan,\'task_name\':str(payload.get(\'task_name\') or product[\'name\']+\'创作任务\')[:120],\'budget_limits\':inputs.get(\'budget_limits\',{}),\'preparation\':\'pending\' if private else \'ready\',**({\'questions\':pooled_questions,\'article_target\':article_target,\'genre_targets\':inputs[\'genre_targets\']} if pooled_questions is not None else {})})\n    from geo_source_cards.article_logic import VERSION\n    atomic_json(root/\'logic_policy.json\',{\'required\':True,\'version\':\'rewrite-v2\'})\n    # Paid calls check balance and reserve transactionally in their worker.\n    # Keep network waits outside the global creation lock.\n    resume(root,check_balance=False)\n    return {\'job_id\':identity,\'reused\':False}\n\ndef action(name,payload,operation_id):\n    if not re.fullmatch(r\'[a-f0-9]{32}\',operation_id):raise ValueError(\'操作编号不正确\')\n    signature=digest({\'action\':name,\'payload\':payload})\n    # Uploads must not wait behind slow paid-job preparation or balance calls.\n    # Keep the original global lock for those operations; serialize knowledge edits\n    # separately, and identical image requests by operation ID.\n    scope = (\'image-actions/\'+operation_id+\'.lock\' if name==\'product_image_upload\'\n             else \'knowledge-actions.lock\' if name in {\'kb_upload\',\'kb_publish\',\'kb_edit\',\'kb_save\'}\n             else \'actions.lock\')\n    with process_lock(BASE/scope,blocking=True):\n        with closing(db()) as conn, conn:\n            old=conn.execute(\'select payload_hash,result from operations where id=?\',(operation_id,)).fetchone()\n            if old:\n                if old[0]!=signature:raise ValueError(\'重复操作编号对应不同内容\')\n                return json.loads(old[1])\n            if name==\'new\':result=create(payload)\n            elif name==\'balance\':result=balance()\n            elif name in {\'skeleton_inspect\',\'skeleton_approve\'}:\n                from geo_source_cards.rewrite_v2.common import cache_root\n                from geo_source_cards.rewrite_v2 import structure_parser,integration\n                root=job_root(payload.get(\'job_id\',\'\'))\n                if read(root/\'rewrite_policy.json\').get(\'workflow\')!=\'rewrite-v2\':raise ValueError(\'该历史任务不使用V2骨架\')\n                cache=cache_root(root)\n                if name==\'skeleton_inspect\':\n                    keys={t.get(\'waiting_skeleton\') for p in (root/\'queue\').glob(\'*/ticket.json\') if (t:=read(p)).get(\'waiting_skeleton\')}\n                    result=[read(cache/\'skeleton\'/(key+\'.json\')) for key in sorted(keys)]\n                else:\n                    with process_lock(root/\'coordinator.lock\',blocking=True):\n                        result=structure_parser.approve(cache,payload.get(\'key\',\'\'),payload.get(\'expected_sha256\',\'\'),payload.get(\'reviewer\',\'\'),skeleton=payload.get(\'skeleton\'))\n                        integration.sync_approvals(root)\n            elif name==\'product_image_upload\':\n                from . import product_images\n                result=product_images.upload(payload)\n            elif name in {\'kb_upload\',\'kb_publish\',\'kb_edit\'}:\n                from . import knowledge_library\n                result={\'kb_upload\':knowledge_library.upload,\'kb_publish\':knowledge_library.publish,\'kb_edit\':knowledge_library.edit}[name](payload)\n            elif name in {\'kb_import\',\'kb_save\',\'plan_save\',\'plan_delete\',\'day_pause\',\'day_resume\'}:\n                from . import studio\n                result={\'kb_import\':studio.import_word,\'kb_save\':studio.save_product,\'plan_save\':studio.save_plan,\'plan_delete\':studio.delete_plan,\'day_pause\':lambda v:studio.day_control(v,True),\'day_resume\':lambda v:studio.day_control(v,False)}[name](payload)\n            elif name==\'materials_settings\':\n                from .materials import save\n                result=save(payload)\n            elif name in {\'materials_pause\',\'materials_resume\'}:\n                from .materials import control\n                result=control(\'pause\' if name==\'materials_pause\' else \'resume\')\n            elif name in {\'pause\',\'resume\'}:\n                root=job_root(payload.get(\'job_id\',\'\'))\n                assert_job_controllable(root)\n                result=pipeline_control.pause(root,\'operator\',\'用户请求排空暂停；已发送API保留收尾\') if name==\'pause\' else resume(root,allow_http_recovery=True)\n            else:raise ValueError(\'操作不存在\')\n            conn.execute(\'insert into operations values(?,?,?)\',(operation_id,signature,json.dumps(result,ensure_ascii=False)))\n            return result\n\ndef assert_job_controllable(root):\n    from . import studio\n    job=read(root/\'job.json\')\n    if job.get(\'studio_plan_id\'):studio.plan(job[\'studio_plan_id\'])\n    if read(root/\'days\'/job.get(\'date\',\'\')/\'day.json\').get(\'status\') in studio.TERMINAL_JOBS:\n        raise ValueError(\'本次执行已结束，不能暂停或继续；请查看已有成稿\')\n\ndef product_label(root,day):\n    """Use the archived daily product, never today\'s mutable legacy input."""\n    path=root/\'days\'/day/\'product.json\'\n    product=read(path) if path.is_file() else read(root/\'product.json\') if root!=SHARED else {}\n    name=str(product.get(\'name\') or \'\').strip();brand=str(product.get(\'brand\') or \'\').strip()\n    return {\'id\':digest({\'name\':name,\'brand\':brand}) if name else \'unknown\',\'name\':name or \'未标注产品\',\'brand\':brand}\n\ndef articles(root, *, summary=False):\n    result=[]\n    revoked={read(p).get(\'word_sha256\') for p in (root/\'revocations\').glob(\'*.json\')}\n    for path in sorted((root/\'approved\').glob(\'*/*/*/receipt.json\')):\n        receipt=read(path);folder=path.parent\n        draft=folder/\'draft.md\';word=folder/\'article.docx\'\n        if receipt.get(\'status\')!=\'accepted_for_user_review\' or receipt.get(\'word_sha256\') in revoked:continue\n        files=receipt.get(\'files\',{})\n        if not files.get(\'draft.md\') or not files.get(\'article.docx\'):continue\n        valid=True\n        for name,expected in files.items():\n            file=folder/name\n            if Path(name).name!=name or file.is_symlink() or not file.is_file() or hashlib.sha256(file.read_bytes()).hexdigest()!=expected:\n                valid=False;break\n        if not valid:continue\n        if summary:\n            result.append({\'id\':folder.relative_to(root/\'approved\').as_posix()})\n            continue\n        # Only original approved receipt directories are downloadable.\n        from .article_export import info\n        metadata=info(root,folder)\n        from geo_source_cards.consumer_voice import issues as voice_issues\n        direct=receipt.get(\'delivery_mode\')==\'direct\'\n        quality_issues=[] if direct or receipt.get(\'workflow\')==\'rewrite-v2\' else voice_issues(draft.read_text(\'utf8\'))\n        if receipt.get(\'workflow\')==\'rewrite-v2\' and not direct:\n            from geo_source_cards.rewrite_v2.quality_reviewer import verify_final\n            try:\n                verify_final(read(folder/\'semantic_review.json\'),read(folder/\'rewrite_context.json\'),read(folder/\'rewrite_material.json\'),draft.read_text(\'utf8\'))\n            except (ValueError,KeyError,TypeError) as error:quality_issues.append(\'V2审核尚未通过：\'+str(error)[:350])\n        elif not direct and read(root/\'logic_policy.json\').get(\'required\'):\n            from geo_source_cards.article_logic import enforce\n            try:\n                product=read(folder/\'logic_product.json\') if (folder/\'logic_product.json\').exists() else read(root/\'days\'/folder.parent.parent.name/\'product.json\')\n                semantic=read(folder/\'semantic_review.json\');arb=None\n                if semantic.get(\'arbitration\'):\n                    from geo_source_cards.review_arbitration import enforce as enforce_arbitration\n                    from geo_source_cards.article_compiler import verify_inputs\n                    knowledge=semantic[\'arbitration\'][\'input\'][\'knowledge\']\n                    verify_inputs(read(folder/\'compilation.json\'),knowledge,product)\n                    arb=enforce_arbitration(semantic,draft.read_text(\'utf8\'),knowledge,product)\n                enforce(read(folder/\'logic_review.json\'),draft.read_text(\'utf8\'),product,arbitration=arb)\n            except (ValueError,KeyError,TypeError) as error:quality_issues.append(\'全文逻辑尚未通过复核：\'+str(error)[:350])\n        from geo_source_cards.article_title import display_title\n        result.append({\'id\':folder.relative_to(root/\'approved\').as_posix(),\'date\':folder.parent.parent.name,\'product\':product_label(root,folder.parent.parent.name),\'title\':display_title(draft.read_text(\'utf8\'),metadata[\'product\'],{\'category\':metadata[\'category\']}) if draft.is_file() else folder.name,\n            \'quality_status\':\'needs_revision\' if quality_issues else \'ready_with_disputes\' if receipt.get(\'quality_status\')==\'ready_with_disputes\' or receipt.get(\'logic_status\')==\'needs_revision\' else \'ready\',\'quality_issues\':quality_issues,\n            \'review_disputes\':receipt.get(\'review_disputes\',[]),\n            \'markdown\':draft.is_file(),\'word\':word.is_file(),\'receipt\':receipt,\'task_name\':metadata[\'task_name\'],\'category\':metadata[\'category\'],\'primary_reference\':metadata[\'primary_reference\']})\n    return result\n\ndef status(*, task_list=False):\n    jobs=[]\n    for path in sorted((BASE/\'runs\').glob(\'*/job.json\'),reverse=True):\n        root=path.parent;job=read(path);tickets=[read(p) for p in (root/\'queue\').glob(\'*/ticket.json\')]\n        counts={}\n        for ticket in tickets:\n            key=ticket.get(\'stage\',\'\')+\':\'+ticket.get(\'state\',\'\');counts[key]=counts.get(key,0)+1\n        day=read(root/\'days\'/job[\'date\']/\'day.json\')\n        from .editorial_status import blocks,execution_health\n        health=execution_health(root,tickets,day)\n        jobs.append({**job,\'quality_blocks\':blocks(root,tickets),\'product\':product_label(root,job[\'date\']),\'control\':pipeline_control.state(root),\'health\':health,\n            \'worker\':read(root/\'geo_worker.json\'),\'queue\':counts,\'articles\':articles(root,summary=True) if task_list else articles(root),\n            \'day\':day})\n    legacy=[] if task_list else articles(SHARED)\n    from . import materials\n    from . import studio\n    studio_state=studio.snapshot(jobs)\n    if task_list:\n        # Task cards and editors only need the archived product name in each plan.\n        studio_state[\'plans\']=[{**p,\'product\':{k:p[\'product\'].get(k,\'\') for k in (\'name\',\'brand\')}} for p in studio_state[\'plans\']]\n        studio_state[\'products\']=[{\'product_id\':p[\'product_id\'],\'version\':p.get(\'version\'),\'product\':{k:p[\'product\'].get(k,\'\') for k in (\'name\',\'brand\')}} for p in studio_state[\'products\']]\n        studio_state[\'pending_import\']=None\n    return {\'ok\':True,\'at\':time.time(),\'jobs\':[] if task_list else jobs,\'settings\':pipeline_control.settings(SHARED),\n            \'legacy_articles\':legacy,\'materials\':materials.status(),\'studio\':studio_state,\n            \'legacy_approved_articles\':len(list((SHARED/\'approved\').glob(\'*/*/*/receipt.json\'))),\n            \'source\':\'专用素材独立保存；可选择只读GEO已有素材\',\'worker\':read(BASE/\'worker_health.json\')}\n\ndef download(identity,article_id,kind,filters=None):\n    root=SHARED if identity==\'legacy-original\' else None if identity==\'all-approved\' else job_root(identity)\n    if kind in {\'bundle\',\'package\'}:\n        import zipfile\n        filters=filters or {};date=filters.get(\'date\',\'\');product=filters.get(\'product\',\'\');source=filters.get(\'source\',\'all\');search=filters.get(\'search\',\'\')\n        if date and not re.fullmatch(r\'\\d{4}-\\d{2}-\\d{2}\',date):raise ValueError(\'筛选日期不正确\')\n        if product and product!=\'unknown\' and not re.fullmatch(r\'[a-f0-9]{64}\',product):raise ValueError(\'筛选产品不正确\')\n        if source not in {\'all\',\'new\',\'legacy-original\'} or not isinstance(search,str) or len(search)>200:raise ValueError(\'筛选条件不正确\')\n        plan=filters.get(\'plan\',\'\')\n        if plan and not re.fullmatch(r\'plan-[a-f0-9]{32}\',plan):raise ValueError(\'任务筛选不正确\')\n        if kind==\'package\' and (root is None or article_id not in {a[\'id\'] for a in articles(root)}):raise ValueError(\'请选择有效成稿\')\n        suffix=\'-\'+digest({\'filters\':filters,\'article\':article_id if kind==\'package\' else \'\'})[:24]\n        path=BASE/\'exports\'/(identity+suffix+\'.zip\');path.parent.mkdir(parents=True,exist_ok=True)\n        temporary=path.with_name(path.name+\'.\'+uuid.uuid4().hex+\'.tmp\')\n        roots=[SHARED]+[p.parent for p in (BASE/\'runs\').glob(\'*/job.json\')] if root is None else [root]\n        from .article_export import write_article\n        with zipfile.ZipFile(temporary,\'w\',zipfile.ZIP_DEFLATED) as archive:\n            manifest=[]\n            for current in roots:\n                if source==\'new\' and current==SHARED or source==\'legacy-original\' and current!=SHARED:continue\n                if plan and read(current/\'job.json\').get(\'studio_plan_id\')!=plan:continue\n                for item in articles(current):\n                    if item.get(\'quality_status\')==\'needs_revision\':continue\n                    if kind==\'package\' and item[\'id\']!=article_id:continue\n                    if date and item[\'date\']!=date or product and item[\'product\'][\'id\']!=product or search.strip().lower() not in item[\'title\'].lower():continue\n                    folder=current/\'approved\'/item[\'id\']\n                    if current.resolve() not in folder.resolve().parents:raise ValueError(\'成稿路径不正确\')\n                    manifest.append(write_article(archive,current,item))\n            archive.writestr(\'导出清单.json\',json.dumps({\'articles\':manifest,\'count\':len(manifest)},ensure_ascii=False,indent=2))\n        temporary.replace(path)\n        with zipfile.ZipFile(path) as checked:\n            if checked.testzip() is not None:raise ValueError(\'压缩包完整性检查失败，请重新下载\')\n            if not json.loads(checked.read(\'导出清单.json\')).get(\'count\'):raise ValueError(\'当前筛选没有可下载的成稿，请调整筛选后重试\')\n        return path\n    if root is None:raise ValueError(\'请选择成稿\')\n    if kind not in {\'markdown\',\'word\',\'info\'}:raise ValueError(\'文件类型不正确\')\n    if not re.fullmatch(r\'[^/\\\\.][^/\\\\]*/[^/\\\\.][^/\\\\]*/[^/\\\\.][^/\\\\]*\',article_id):raise ValueError(\'成稿编号不正确\')\n    folder=(root/\'approved\'/article_id).resolve()\n    if root.resolve() not in folder.parents or not (folder/\'receipt.json\').is_file():raise ValueError(\'成稿不存在\')\n    available={a[\'id\']:a for a in articles(root)}\n    if article_id not in available:raise ValueError(\'成稿已撤回或文件校验未通过，不作为可下载成稿\')\n    if kind!=\'info\' and available[article_id].get(\'quality_status\')==\'needs_revision\':raise ValueError(\'这篇旧稿未通过正文质量复核，已停止下载，修订通过后恢复\')\n    if kind==\'info\':\n        from .article_export import info,describe,logs\n        metadata=info(root,folder);path=BASE/\'exports\'/(\'info-\'+digest([identity,article_id])[:24]+\'.md\')\n        atomic_write(path,describe(metadata)+\'\\n## 执行日志\\n\\n```json\\n\'+json.dumps(logs(root,metadata),ensure_ascii=False,indent=2)+\'\\n```\\n\')\n        return path\n    path=folder/(\'draft.md\' if kind==\'markdown\' else \'article.docx\')\n    if not path.is_file():raise ValueError(\'文件不存在\')\n    from .article_images import project\n    return project(root,folder)[kind]\n'}}
TESTS={'test_jsonl_records.py': 'import json\nimport tempfile\nimport unittest\nfrom pathlib import Path\nfrom . import materials\nfrom geo_source_cards.source_analysis import load_records\n\n\nclass JsonlRecordsTests(unittest.TestCase):\n    def test_unicode_separators_preserved_and_duplicates_deduplicated(self):\n        with tempfile.TemporaryDirectory() as directory:\n            root=Path(directory)\n            path=root/\'days/2026-10-31/baidu_ai/results.jsonl\'\n            path.parent.mkdir(parents=True)\n            row={\'question\':\'题目\',\'model\':\'baidu_ai\',\'task_id\':\'a\',\'captured_at\':1,\n                 \'text\':\'原文\\u0085下一段\\u2028仍在原文\\u2029末段\',\'body_capture_complete\':True}\n            text=json.dumps(row,ensure_ascii=False)\n            path.write_text(text+\'\\n\'+text+\'\\n\',encoding=\'utf8\')\n            self.assertEqual(materials.records(\'2026-10-31\',\'题目\',[\'baidu_ai\'],root),[row])\n            self.assertEqual(materials.read_lines(path),[row,row])\n            self.assertEqual(load_records(path),[row,row])\n\n    def test_real_corruption_is_not_silently_ignored(self):\n        with tempfile.TemporaryDirectory() as directory:\n            path=Path(directory)/\'broken.jsonl\'\n            path.write_text(\'{"question":"truncated\\n\',encoding=\'utf8\')\n            for reader in (materials.read_lines,load_records):\n                with self.assertRaises(json.JSONDecodeError):reader(path)\n', 'test_response_framing.py': 'import json,unittest\nfrom .client import recover_transport_json\n\nclass ResponseFramingTests(unittest.TestCase):\n    def test_exact_dsml_tail_preserves_draft(self):\n        result={\'draft_markdown\':\'# 标题\\n正文“引号”\\n尾段\'}\n        suffix=\'</｜｜DSML｜｜ parameter>\\n</｜｜DSML｜｜ invoke>\\n</｜｜DSML｜｜ calls>\'\n        self.assertEqual(recover_transport_json(json.dumps(result,ensure_ascii=False)+suffix)[0],result)\n\n    def test_extra_prose_or_second_object_not_accepted(self):\n        for tail in [\' instructions\',\'{}\',\'</script>\',\'\']:\n            with self.assertRaises(ValueError):recover_transport_json(\'{"draft_markdown":"text"}\'+tail)\n\n    def test_stray_quote_only_with_complete_skeleton(self):\n        result={\'article_type\':\'ranking\',\'tone\':\'客观\',\'article_structure\':[\'开头\',\'比较\'],\n                \'writing_rhythm\':\'先慢后快\',\'special_style_elements\':[],\'forbidden_pattern\':[]}\n        value=json.dumps(result,ensure_ascii=False).replace(\'], "writing_rhythm"\',\']", "writing_rhythm"\')\n        self.assertEqual(recover_transport_json(value)[0],result)\n        with self.assertRaises(ValueError):recover_transport_json(\'{"article_structure":["x"]", "writing_rhythm":"y"}\')\n', 'test_source_cache.py': "import hashlib\nimport tempfile\nimport unittest\nfrom pathlib import Path\nfrom geo_source_cards.runtime import atomic_json\nfrom .source_cache import SourceCache, failure_kind\n\n\nclass SourceCacheTests(unittest.TestCase):\n    def test_reuses_previous_round_without_extending_age(self):\n        with tempfile.TemporaryDirectory() as directory:\n            root = Path(directory); url = 'https://example.com/a'\n            key = hashlib.sha256(url.encode()).hexdigest() + '.json'\n            old = root / 'private_source_analysis-supplement-2/article_cache' / key\n            atomic_json(old, dict(status='fetched', requested_url=url, fetched_at=100, text='body'))\n            calls = []\n            fetch = lambda u: calls.append(u) or dict(status='fetched', text='new')\n            cache = SourceCache(root, fetch, clock=lambda: 200)\n            self.assertEqual(cache(url)['text'], 'body')\n            self.assertEqual(calls, [])\n            # Downstream analysis stamps a new fetched_at; actual read age wins.\n            result = {**cache(url), 'fetched_at': 86500}\n            atomic_json(old, result)\n            cache.clock = lambda: 86501\n            self.assertEqual(cache(url)['text'], 'new')\n            self.assertEqual(calls, [url])\n\n    def test_dns_failure_retries_after_short_cooldown(self):\n        with tempfile.TemporaryDirectory() as directory:\n            calls = []; now = [100]\n            def fetch(url):\n                calls.append(url)\n                return dict(status='failed', attempts=[dict(error='Temporary failure in name resolution')]) if len(calls)==1 else dict(status='fetched', text='recovered')\n            cache = SourceCache(directory, fetch, clock=lambda: now[0])\n            self.assertEqual(cache('https://example.com/a')['failure_kind'], 'dns')\n            now[0] = 159\n            self.assertEqual(cache('https://example.com/a')['status'], 'failed')\n            self.assertEqual(len(calls), 1)\n            now[0] = 160\n            self.assertEqual(cache('https://example.com/a')['text'], 'recovered')\n\n    def test_corrupt_and_wrong_url_cache_do_not_supply_content(self):\n        with tempfile.TemporaryDirectory() as directory:\n            url = 'https://example.com/a'; root = Path(directory)\n            p = root/'source_read_cache'/(hashlib.sha256(url.encode()).hexdigest()+'.json')\n            p.parent.mkdir();p.write_text('{')\n            calls = []\n            cache = SourceCache(root, lambda u: calls.append(u) or dict(status='fetched', text=u), clock=lambda:100)\n            self.assertEqual(cache(url)['text'], url)\n            atomic_json(p, dict(status='fetched', requested_url='https://example.com/b', fetched_at=100))\n            self.assertEqual(cache(url)['text'], url)\n            self.assertEqual(len(calls), 2)\n\n    def test_failure_reasons(self):\n        self.assertEqual(failure_kind(dict(attempts=[dict(error='HTTP 404')])), 'not_found')\n        self.assertEqual(failure_kind(dict(error='Verification/access-denied page is not an article')), 'verification')\n\n\nif __name__ == '__main__':\n    unittest.main()\n", 'test_shared_source_cache.py': "import hashlib,json,sqlite3,tempfile,unittest\nfrom datetime import datetime\nfrom pathlib import Path\nfrom zoneinfo import ZoneInfo\nfrom .source_cache import SourceCache\n\nclass SharedSourceCacheTests(unittest.TestCase):\n def setUp(self):\n  self.tmp=tempfile.TemporaryDirectory();self.root=Path(self.tmp.name);self.db=self.root/'content.sqlite'\n  self.url='https://baijiahao.baidu.com/s?id=123';self.body='真实的完整文章内容。'*60\n  with sqlite3.connect(self.db) as db:\n   db.execute('create table source_content(url text primary key,final_url text,status text,fetched_at text,extraction_quality text,content_text text,text_length integer,content_hash text,title text,extraction_method text)')\n   db.execute('insert into source_content values(?,?,?,?,?,?,?,?,?,?)',(self.url,self.url,'ok','2026-10-31 08:00:00','high',self.body,len(self.body),hashlib.sha256(self.body.encode()).hexdigest(),'原文标题','article_node'))\n  self.at=datetime(2026,10,31,8,tzinfo=ZoneInfo('Asia/Shanghai')).timestamp();self.calls=[]\n  self.cache=SourceCache(self.root/'job',lambda url:self.calls.append(url) or {'status':'failed'},clock=lambda:self.at+3600,content_db=self.db)\n def tearDown(self):self.tmp.cleanup()\n def test_reuse_exact_snapshot_preserves_age_and_database(self):\n  before=self.db.read_bytes();value=self.cache(self.url)\n  self.assertEqual(value['status'],'fetched');self.assertEqual(value['source_read_at'],self.at)\n  self.assertEqual(value['reused_from'],'geo_source_content_sqlite');self.assertEqual(self.calls,[])\n  self.assertEqual(self.db.read_bytes(),before)\n def test_expired_snapshot_is_not_reused(self):\n  self.cache.clock=lambda:self.at+86400\n  self.assertIsNone(self.cache.shared_article(self.url))\n def test_quality_and_hash_are_required(self):\n  for field,value,original in [('extraction_quality','low','high'),('content_hash','wrong',hashlib.sha256(self.body.encode()).hexdigest()),('status','blocked','ok')]:\n   with self.subTest(field=field):\n    with sqlite3.connect(self.db) as db:db.execute('update source_content set '+field+'=?',(value,))\n    self.assertIsNone(self.cache.shared_article(self.url))\n    with sqlite3.connect(self.db) as db:db.execute('update source_content set '+field+'=?',(original,))\n def test_verification_redirect_and_other_url_rejected(self):\n  self.assertIsNone(self.cache.shared_article(self.url+'4'))\n  with sqlite3.connect(self.db) as db:db.execute('update source_content set final_url=?',('https://wappass.baidu.com/static/captcha/tuxing.html',))\n  self.assertIsNone(self.cache.shared_article(self.url))\n"}
